js:var RG_ALLOW_TAB=true;
/* 原地刷新状态：rg_kw=搜索关键词、rg_tab=二级分类筛选（两者互斥）、rg_page=页码。
   仅列表页规则定义 RG_ALLOW_TAB=true；详情页规则不带此开关。
   一级分类切换后旧二级分类状态会串味（一级分类栏是原生切换、无 JS 钩子），
   因此校验当前一级分类与状态里的分类是否一致，不一致直接丢弃。
   搜索必须走 path 形式 /search/<关键词>：query 形式 ?search=xx 的 SSR 里
   searchList 恒为空（实测 totalCount=0），path 形式才有数据（实测 10 条/total 98）。 */
var raw='';
try{
  var _rgOn=(typeof RG_ALLOW_TAB!=='undefined')&&!!RG_ALLOW_TAB;
  /* 页码：http 自动翻页时海阔会递增 MY_PAGE，用它判断是否首屏，
     避免「翻页追加」时把二级分类行/搜索框也重复 push 到列表尾部。 */
  var HG_PG=1;
  try{ HG_PG=parseInt((typeof MY_PAGE!=='undefined'&&MY_PAGE)?MY_PAGE:1,10)||1; }catch(e){ HG_PG=1; }
  var _rgPg=1;
  try{ _rgPg=parseInt(getMyVar('rg_page','1'),10)||1; }catch(e){ _rgPg=1; }
  var _rgKw='';
  try{ _rgKw=String(getMyVar('rg_kw','')||''); }catch(e){ _rgKw=''; }
  var _rgTab='';
  try{ _rgTab=String(getMyVar('rg_tab','')||''); }catch(e){ _rgTab=''; }
  /* 页面切换（例如点一级分类栏）后所有原地刷新状态作废：
     rg_ctx 记住状态所属页面，当前页 URL 与它不一致就直接丢弃并清状态。 */
  var _curUrl=String((typeof MY_URL!=='undefined')?MY_URL:'');
  if(_curUrl && (_rgKw || _rgTab)){
    var _rgCtx=''; try{ _rgCtx=String(getMyVar('rg_ctx','')||''); }catch(e){ _rgCtx=''; }
    if(_rgCtx && _rgCtx!==_curUrl){
      try{ putMyVar('rg_kw',''); putMyVar('rg_tab',''); putMyVar('rg_tabn',''); putMyVar('rg_ctx',''); putMyVar('rg_page','1'); }catch(e){}
      _rgKw=''; _rgTab='';
    }else if(!_rgCtx){
      try{ putMyVar('rg_ctx',_curUrl); }catch(e){}
    }
  }
  var _rgU='';
  if(_rgOn && _rgKw){
    _rgU='https://hongguoduanju.com/search/'+encodeURIComponent(_rgKw)+'?tab=real-drama&page='+_rgPg;
  }else if(_rgOn && _rgTab){
    var _curCat=''; try{ var _m=String((typeof MY_URL!=='undefined')?MY_URL:'').match(/\/category\/([^\/?]+)/); _curCat=_m?_m[1]:''; }catch(e){}
    var _tabCat=''; try{ var _m2=_rgTab.match(/\/category\/([^\/?]+)/); _tabCat=_m2?_m2[1]:''; }catch(e){}
    if(!_curCat || !_tabCat || _curCat!==_tabCat){
      try{ putMyVar('rg_tab',''); putMyVar('rg_tabn',''); putMyVar('rg_page','1'); }catch(e){}
      _rgTab='';
    }else{
      _rgU=_rgTab+((_rgTab.indexOf('?')>=0)?'&':'?')+'page='+_rgPg;
    }
  }
  /* v80：**自己取第 N 页**（不再依赖海阔那次 GET）——模板里的 `?page=fypage` 已经挪到 tag 位，
     海阔只请求分类首页。这里按 MY_PAGE 取真正的第 N 页；站点对超范围页返回 404/空正文时
     raw 保持为空、**并且不再回退到 getResCode()**（那会拿到首页内容、把第一页重复渲染一遍），
     最终 d=[] ⇒ 海阔认为没有更多、停止翻页 —— 用户再上拉也不会报 404 网络错误。 */
  var _rgOwn=false;
  if(!_rgU && typeof fetch==='function' && _curUrl){
    var _rgBase=_curUrl.replace(/#.*$/,'').replace(/[?&]page=\d+/,'');
    if(_rgBase.indexOf('/category/')>=0 || _rgBase.indexOf('/rank/')>=0){
      _rgOwn=true;
      _rgU=_rgBase+(_rgBase.indexOf('?')>=0?'&':'?')+'page='+HG_PG;
    }
  }
  if(_rgU && typeof fetch==='function'){
    try{ raw=String(fetch(_rgU,{headers:{'Referer':'https://hongguoduanju.com','User-Agent':'Googlebot'},timeout:20000})||''); }catch(e){ raw=''; }
  }
}catch(e){ raw=''; }
if(!raw && !_rgOwn){
  raw=(typeof getResCode==='function')?getResCode():((typeof result!=='undefined'&&result)?result:(typeof input!=='undefined'?input:''));
}
var d=[];
var j=null;
var _ri=raw.indexOf('_ROUTER_DATA');
if(_ri>=0){
  var _eq=raw.indexOf('=',_ri);
  var _st=-1;
  for(var s=_eq;s<raw.length;s++){if(raw.charAt(s)==='{'){_st=s;break;}}
  if(_st>=0){
    var _dp=0;var _ed=-1;
    for(var i=_st;i<raw.length;i++){
      var _c=raw.charAt(i);
      if(_c==='{')_dp++;
      else if(_c==='}'){_dp--;if(_dp===0){_ed=i;break;}}
    }
    if(_ed>_st){try{j=JSON.parse(raw.substring(_st,_ed+1));}catch(e){j=null;}}
  }
}

var HG_SITE = 'https://hongguoduanju.com';
/* 榜单页只有「爬虫 UA」才在 SSR 里带 rankList（普通浏览器 UA 返回空 content），
   所以顶层 url 模板与按钮链接都随带 User-Agent 头修饰；
   四个排行榜已并入一级分类栏（class_url，排在「搜索」之后），点它即按分类 URL 重新加载本页。 */
var HG_HDR = ';get;UTF-8;{Referer@https://hongguoduanju.com&&User-Agent@Googlebot}';

/* ---- 原地切换（不新开页面）--------------------------------------------
   $('hiker://empty').lazyRule(fn, params) 是海阔内置的「点击执行」绑定：
   点击时执行 fn(params)，返回 'hiker://empty' 不发起导航；fn 内写状态 MyVar
   后调 refreshPage(true)，当前列表页的 find_rule 立即重跑并按新状态取数渲染。
   （同款写法已在黄果短剧规则上设备实测通过。） */
var HG_TAB='', HG_TABN='', HG_TABPG=1, HG_KW='';
try{
  HG_TAB=String(getMyVar('rg_tab','')||'');
  HG_TABN=String(getMyVar('rg_tabn','')||'');
  HG_TABPG=parseInt(getMyVar('rg_page','1'),10)||1;
  HG_KW=String(getMyVar('rg_kw','')||'');
}catch(e){ HG_TAB=''; HG_TABN=''; HG_TABPG=1; HG_KW=''; }
var HG_CAN_TAB=(typeof RG_ALLOW_TAB!=='undefined')&&!!RG_ALLOW_TAB
             &&(typeof $==='function')&&(typeof fetch==='function')
             &&(typeof refreshPage==='function');

function hgTabClick(u,n){
  return $('hiker://empty').lazyRule(function(p){
    try{ putMyVar('rg_tab',p.u||''); putMyVar('rg_tabn',p.n||''); putMyVar('rg_page','1'); }catch(e){}
    try{ refreshPage(true); }catch(e){}
    return 'hiker://empty';
  }, {u:u||'', n:n||''});
}
/* 按钮：二级分类点它即原地刷新（写 rg_tab + refreshPage），不新开页面。
   一级分类栏（海阔 header 行）的真实渲染见 ArticleListAdapter.java 1499-1519：
     布局 item_article_header_item；选中 = 背景 drawable tab_item_selected
     + 文字色 R.color.yellowAction（跟随主题色）；未选中 = tab_item_default
     + R.color.black_666；padding 10/3dp、项间距 5dp。
   规则侧只能给纯色 backgroundColor（drawable 与 textColor 都指定不了），
   所以命中项用浅绿纯色近似；文字色保持布局默认（不再加 ““ ”” 标记，避免被
   setSpanText 转成内置的红/橙字）。 */
function hgBtn(title, colType, u, n, hit){
  var extra = hit ? { backgroundColor:'#DCF2E2' } : {};
  if (HG_CAN_TAB) {
    return { title:title, col_type:colType, url:hgTabClick(u,n), extra:extra };
  }
  return { title:title, col_type:colType, url:u + '?page=1' + HG_HDR, extra:extra };
}

/* 搜索框：onChange 是海阔官方支持的输入监听；点确定执行 url 里的 js（input 即输入值）。
   这里不跳新页面，而是写状态 + refreshPage，结果原地出现在下方。 */
/* v43：**搜索框和「清理」按钮做成同一行**（用户要求：搜索框缩小点、后面补上按钮）。
   海阔的输入行布局（反编译 res/layout/item_input.xml）本身就是
   「一个黑边框（check_bg_white：2dp 描边 + 8dp 圆角）里 = 输入框 + 细分隔线 + 右侧一个按钮」，
   按钮文字取自 item.title，且**只有一个按钮位**（只有一个 search TextView，且是
   `setText(title)` 纯文本、不吃 HTML）——所以「搜索」和「清理」只能共用这一个按钮：
   v44 起按钮文字写成 **「搜索/清理」**（用户要求两个字样一起显示），
   输入区自然被压窄，按钮就贴在它右边、同一个黑框里（= 用户要的「搜索框缩小点，后面补上按钮」）。
   另外反编译 ArticleListAdapter.bindForInputHolder 确认：**键盘回车/确定 = 点这个按钮**
   （ViewTool.setOnEnterClickListener → search.performClick()），所以 url 必须按内容分支：
     · 输入框有字 → 当搜索用（写 rg_kw + refreshPage，结果原地刷在下方）
     · 输入框为空 → 当清理用（readFile+eval 装回清缓存库，全清一次、报数、原地刷新）
   即「打字后回车/点按钮 = 搜索」「清空后点按钮 = 清理」，两个功能都在同一行同一条黑框内，
   也没有 icon_1_search 那个多余的扫描图标。 */
function hgSearchInput(){
  /* v74：**清理标记在逻辑库里处理**（跟 v71 的「后台补季/补全」一样，不再依赖模板正文那段）——
     用户点「搜索/清理」而输入为空时，按钮只写 rg_gc 标记 + 刷新本页；本函数首页/搜索页每次渲染都会跑到，
     在这里读到标记就直接跑 hgCacheGc()（它就在本库里）并把结果 toast 出来。
     放在库里 ⇒ 老版本导入的规则只要库热更上来，清理按钮照样能用。模板末尾那段保留着当兜底：
     标记已经被这里清掉 = 空操作，不会清两遍。 */
  try {
    if (String(getMyVar('rg_gc','')) === '1') {
      putMyVar('rg_gc', '');
      var _rgv = { n:0, mb:0 };
      try { _rgv = hgCacheGc(); } catch (e0) {}
      /* v75：**播报挪到渲染之后再发** —— 上面这步是在「本页正在重建列表」的过程里跑的，
         这时候直接 toast 会被海阔吞掉（用户反馈「清理完成后没有 toast 内容」）。
         放到后台线程里等 400ms（本页 setResult 早就完成了）再播报，跟「补全结束」同一套做法。 */
      try {
        var _rgmsg = '已清理 ' + _rgv.n + ' 个文件，释放 ' + _rgv.mb + 'MB';
        if (typeof java !== 'undefined' && java && java.lang && java.lang.Thread) {
          var _rgth = new java.lang.Thread(function () {
            try { java.lang.Thread.sleep(400); } catch (eS) {}
            try { toast(_rgmsg); } catch (eT) {}
          });
          _rgth.start();
        } else { toast(_rgmsg); }
      } catch (e1) {}
    }
  } catch (eG) {}
  return {
    col_type:'input', title:'搜索/清理', desc:'输入片名/演员',
    extra:{
      onChange:"try{ putMyVar('rg_kw',String(input||'')); putMyVar('rg_page','1'); }catch(e){}",
      defaultValue: HG_KW || ''
    },
    url: "(function(){ var kw=''; try{ kw=String((typeof input!=='undefined'&&input)||'').replace(/^\\s+|\\s+$/g,''); }catch(e0){}"
       + " if(kw){"
       +   " try{ putMyVar('rg_kw',kw); putMyVar('rg_page','1'); }catch(e){}"
       +   " try{ refreshPage(true); }catch(e){}"
       + " } else {"
       /* v70：清理由**页面自己**跑（hgCacheGc 就在 PAGE_LIB 里）：这里只写标记 + 刷新，
          不再需要把整套清理源码落成 rg_gc.js 给点击上下文 eval。 */
       +   " try{ putMyVar('rg_gc','1'); refreshPage(false); }catch(e){}"
       + " }"
       + " return 'hiker://empty'; })()"
  };
}
/* v109：**登录功能已按用户要求整体移除** —— 原 v104~v108 的「账号登录面板」
   （凭证登录 / 手机号+验证码 / 网页登录取凭证 / 退出登录）与搜索框的登录入口一并删掉；
   rglib 里对应的账号 API（accountGet / accountSave / accountClear / withAcct / accountVerify /
   sendLoginCode / smsLoginCheck / userInfo / rgQs）也一并移除。 */
/* 搜索状态提示行已移除。 */

/* 从 loaderData 里挑出各页面形态的数据
   注意：不同页面的字段层级不同 —— 榜单页是 loaderData[x].content.rankList，
   分类页是 loaderData[x].recommendList，搜索页是 loaderData[x].searchList，
   剧集页是 loaderData[x].seriesDetail，所以 content 要下钻一层。 */
function hgDig(ld){
  var o = { search: null, rec: null, rank: null, detail: null, sel: null, cat: null };
  for (var k in ld) {
    var v = ld[k];
    if (!v || typeof v !== 'object') continue;
    var w = (v.content && typeof v.content === 'object') ? v.content : v;
    if (w.searchList) o.search = w.searchList;
    if (w.recommendList) o.rec = w.recommendList;
    if (w.rankList) o.rank = w.rankList;
    if (v.seriesDetail) o.detail = v.seriesDetail;
    if (w.selectorList && w.selectorList.length) o.sel = w.selectorList[0].items || [];
    if (v.categoryRoute) o.cat = v.categoryRoute.contentType;
    else if (w.categoryRoute) o.cat = w.categoryRoute.contentType;
  }
  return o;
}

/* v16 回撤：一级分类恢复由规则自带分类栏（class_name/class_url）承载，
   不再用页面内自建按钮（那套会导致三行行距不统一、还可能因为清空 class_url
   而让 fyclass 失去来源、首页直接报错）。 */

/* 排行榜已并入一级分类栏（class_url，见规则顶层 class_name/class_url），
   页面内不再自建排行榜按钮行，也不再需要「← 返回」。 */



/* 二级分类行：自建 scroll_button 行（用当前一级分类页面的 selectorList 渲染 ⇒ 联动）。
   注意：不要用 {type:'header',desc:'area'} 那种原生 header 项 —— header 行由海阔
   自己按规则字段管理（adapter 按 title 缓存 holder），规则里再 push 会在每次
   切分类时**累积多出一行**（实测 BUG）。自建按钮是普通列表项，随页面重建，不累积。 */
function hgAreaRow(d, sel, cat){
  if (!sel || !sel.length || !cat) return;
  var all = HG_SITE + '/category/' + cat;
  /* 未选任何二级分类时默认高亮「全部」，与一级分类栏「总有一项选中」的观感一致 */
  d.push(hgBtn('全部', 'scroll_button', all, '全部', HG_TAB ? (HG_TAB === all) : true));
  for (var i = 0; i < sel.length; i++) {
    var tu = HG_SITE + '/category/' + cat + '/' + sel[i].selector_item_id;
    var nm = sel[i].show_name;
    d.push(hgBtn(nm, 'scroll_button', tu, nm, HG_TAB === tu));
  }
}

/* 剧集卡片：只取图片 / 名字 / ID。
   注意：点卡片必须进「规则自己的采集页」而不是网页 —— 榜单/二级分类现在都由本页
   原地刷新渲染，而海阔下钻的 dealRule **不拷贝 detail_find_rule**，所以卡片若用
   普通 http 链接会落到「网页打开」分支。改用 hiker://page/ep 子页面
   （pages 会被子规则继承），子页面的 url 由 item.extra.url 指定。 */
/* v35：**列表卡片标题要能看见季号** —— 卡片只有一行宽度，站点给多季剧起的长名字
   （实测「持械入宋：第八季」）在卡片上被截成「持械入宋：第八」，季号看不见。
   规则（按用户指定）：**剧名里含季号时，标题 =「剧名前四个字 + 第N季」**
   （「持械入宋：第八季」→「持械入宋第8季」）；不含季号的剧名原样显示。
   本函数放在 PAGE_LIB：列表页规则（find_rule/searchFind）只带 PAGE_LIB、不带 SEASON_LIB，
   所以自带一份季号解析（逻辑与 SEASON_LIB 的 hgsSeasonNum 一致）。 */
var HG_CN_NUM = { '零':0,'一':1,'两':2,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9 };
function hgSnStr(t){
  t = String(t || '');
  if (/^\d+$/.test(t)) return String(parseInt(t, 10));
  if (t.indexOf('十') >= 0) {
    var p = t.split('十');
    var hi = p[0] ? (HG_CN_NUM[p[0]] || 0) : 1;
    var lo = (p[1] && p[1].length) ? (HG_CN_NUM[p[1]] || 0) : 0;
    return String(hi * 10 + lo);
  }
  return String(HG_CN_NUM[t] != null ? HG_CN_NUM[t] : 1);
}
/* v71：**只取季号标记**（'第8季'）—— 用户要求「封面剧名别改，把第*季放到封面里「全*集」前面」，
   所以剧名原样显示、这个标记用在卡片 desc 的「全N集」前（见 hgCards）。
   本函数放在 PAGE_LIB：列表页规则（find_rule/searchFind）只带 PAGE_LIB、不带 SEASON_LIB，
   所以自带一份季号解析（逻辑与季库里的实现一致）。 */
function hgSeasonTag(name){
  var s = String(name == null ? '' : name).split('\n').join('').trim();
  /* 只认「第N季」（任意位置）或「N季」结尾（站点有「…之无灵证道41季」这种不带「第」的写法）；
     中文数字的裸「N季」不认，免得把《人间四季》这类剧名当成第 4 季。 */
  var m = s.match(/第\s*([0-9]{1,3}|[一二三四五六七八九十]{1,3})\s*季/)
       || s.match(/([0-9]{1,3})\s*季\s*$/);
  if (!m) return '';
  return '第' + hgSnStr(m[1]) + '季';
}
/* v79：版本信息行整块删掉（用户要求：不要列表末尾那行「规则 vX · 逻辑库 vY」）。
   要核对版本时看更新弹窗 / 规则 JSON 的 version 字段即可。 */
/* v80：**漫画分类判定** —— 站点 /category/comic 下面是条漫（图片内容），没有视频流，
   按视频点播必然没反应。判定只看当前页 URL，**0 额外请求**；注意排掉 /category/comic-drama（漫剧=视频）。 */
function hgIsComicPage(){
  try {
    var u = String((typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : ((typeof fyclass !== 'undefined') ? fyclass : ''));
    return u.indexOf('/category/comic') >= 0 && u.indexOf('/category/comic-drama') < 0;
  } catch (e) { return false; }
}
function hgCards(d, list, isRank){
  for (var i = 0; i < list.length; i++) {
    var it = list[i] || {};
    var vd = it.video_data || {};                 /* 搜索结果的剧集数据包在 video_data 里 */
    var sid = it.series_id || it.seriesId || it.id || vd.series_id || '';
    if (!sid) continue;
    var cover = it.series_cover || it.cover || it.pic || vd.series_cover || '';
    var nm = it.series_name || it.title || it.name || vd.series_title || '';
    var _tag = hgSeasonTag(nm);                   /* v71：「第N季」标记（剧名不再改写） */
    var _ep = String(it.episode_right_text || vd.episode_right_text || '');
    var desc = isRank
      ? ((it.rank ? ('No.' + it.rank + '  ') : '') + (it.heatText || '') + (it.scoreText ? ('  ' + it.scoreText) : ''))
      : ((_tag ? (_tag + ' · ' + _ep) : _ep) + '\n' +
         String(it.series_intro || it.description || vd.series_intro || '').substring(0, 40));
    d.push({
      title: nm,
      img: cover + '@Referer=' + HG_SITE,
      desc: String(desc || '').substring(0, 120),
      url: 'hiker://page/ep',
      /* v58：**extra 里必须写死 pageTitle**，否则海阔按「上一页标题 + '-' + 本条标题」拼子页标题
