var HG_CLOUD_HDR   = { 'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/126 Safari/537.36',
                       'Referer':'https://gitcode.com/' };
function hgCloudGet(us){
  for (var i = 0; i < (us ? us.length : 0); i++) {
    if (!us[i]) continue;
    try {
      var s = String(fetch(us[i], { headers:HG_CLOUD_HDR, timeout:20000 }) || '');
      if (s && s.length > 800) return s;
    } catch (e) {}
  }
  return '';
}
/* 返回「本轮要覆盖应用的库源码」：缓存新鲜→直接用；过期→抓远端（抓到就更新缓存）；
   抓不到→仍返回缓存里的旧版本；都没有→返回 ''（各模板继续用内置实现兜底）。 */
function hgCloudLibText(){
  var now = new Date().getTime(), txt = '', st = 0;
  try { txt = String(readFile(HG_CLOUD_CACHE, 0) || ''); } catch (e) { txt = ''; }
  try { st = parseInt(String(readFile(HG_CLOUD_MARK, 0) || '0'), 10) || 0; } catch (e0) { st = 0; }
  if (txt && st && (now - st) < HG_CLOUD_TTL) return txt;
  var fresh = '';
  try { fresh = hgCloudGet([HG_CLOUD_LIB, HG_CLOUD_LIB2]); } catch (e1) { fresh = ''; }
  if (!fresh || fresh.indexOf('function ') < 0) return txt;
  try { saveFile(HG_CLOUD_CACHE, fresh, 0); saveFile(HG_CLOUD_MARK, String(now), 0); } catch (e2) {}
  /* v42/v58：**更新提示全部走海阔原生 `confirm()` 系统弹窗**，页面里不留东西，
     也**不再弹底部的 toast**（v58 用户要求：「更新时不需要下方的toast了」）：
       ① 逻辑库热更：这份是"新拉到的库"（与旧缓存不同）时，取库里头的 // RG_LIB_V= 与
          // RG_NOTE=（更新说明）弹一次；每个版本只弹一次（rg_cloud_noted.txt 记版本号）。
       ② 规则结构更新：远端库版本 > 本地规则版本时，自动下载规则 JSON 存到「文件→rules」并复制到剪贴板。
     两条同时命中（我一般两个版本号一起 bump）就**并进同一个弹窗**，只弹一次，不会连环弹两个。
     注意：confirm 的 confirm/cancel 是**新的 JS 上下文**里的代码字符串（海阔拿它 eval，
     见 ArticleListIsland.lambda$confirm$1），不能引用本页变量/函数，所以只写 refreshPage。 */
  try {
    var _upNotes = [];                 /* 本次要弹给用户的内容（可能两条） */
    if (txt !== fresh) {
      var nv = 0; try { var m2 = fresh.match(/RG_LIB_V\s*=\s*(\d+)/); nv = m2 ? (parseInt(m2[1], 10) || 0) : 0; } catch (e8) {}
      var note = ''; try { var m3 = fresh.match(/\/\/\s*RG_NOTE=(.*)/); note = m3 ? String(m3[1]).replace(/[\r\n]+$/, '') : ''; } catch (e9) {}
      var shown = 0; try { shown = parseInt(String(readFile(HG_CLOUD_NOTED, 0) || '0'), 10) || 0; } catch (e10) { shown = 0; }
      if (nv > shown && nv > 0) {
        try { saveFile(HG_CLOUD_NOTED, String(nv), 0); } catch (e11) {}
        _upNotes.push('已更新到 v' + nv + (note ? ('\n' + note.split('；').join('\n· ')) : ''));
      }
    }
    try {                              /* ② 结构更新：远端库版本 > 本地规则版本 → 自动下载规则 JSON */
      var m = fresh.match(/RG_LIB_V\s*=\s*(\d+)/);
      var rv = m ? (parseInt(m[1], 10) || 0) : 0;
      var lv = 0; try { lv = parseInt(String((typeof HG_VER !== 'undefined') ? HG_VER : '0'), 10) || 0; } catch (e3) { lv = 0; }
      if (rv > lv) {
        var j = hgCloudGet([HG_CLOUD_RULE, HG_CLOUD_RULE2]);
        if (j && j.indexOf('"find_rule"') >= 0) {
          try { saveFile('hiker://files/rules/红果短剧_rule_v' + rv + '.json', j); } catch (e4) {}
          /* v77：**别再往剪贴板塞 620KB 规则本体** —— 反编译取证：ClipboardUtil.copyToClipboard 超过 10240 字符
           写不进剪贴板（实测表现：剪贴板里什么都没有、没法粘贴），AutoImportHelper 读口令时超过 51200 字节
           也会被拦 ⇒ 大规则只能用**直链形态的云口令**。这里用官方「导入规则示例」的写法
           `<规则 JSON 直链>@import=js:fetch(input)`：口令只有 110 字节、剪贴板放得下，海阔识别后会自己 fetch
           直链、把返回的**完整规则**当规则文本导入（AutoImportHelper → ArticleListRuleEditActivity.editRule）。
           完整 JSON 另存于 文件→rules，作为完全离线的兜底。 */
        try { setClipboard(String(HG_CLOUD_RULE2 || HG_CLOUD_RULE || '') + '@import=js:fetch(input)'); } catch (e5) {}
          _upNotes.push('规则结构已更新到 v' + rv + '：导入口令已复制到剪贴板（切到桌面再回到海阔即会提示导入，'
                        + '也可在「添加规则 → 网络导入」里粘贴）；完整 JSON 另存于 文件→rules/红果短剧_rule_v' + rv + '.json');
        }
      }
    } catch (e7) {}
    if (_upNotes.length) {
      try {
        if (typeof confirm === 'function') {
          confirm({ title:'红果短剧 更新提示', content:_upNotes.join('\n\n'),
                    confirm:'try{ refreshPage(false); }catch(e){}', cancel:'' });
        }
      } catch (e13) {}
    }
  } catch (e16) {}
  return fresh;
}


