    }
  }
  var _rgU='';
  if(_rgOn && _rgKw){
    _rgU='https://hongguoduanju.com/search/'+encodeURIComponent(_rgKw)+'?tab=real-drama&page='+_rgPg;
  }else if(_rgOn && _rgTab){
    var _curCat=''; try{ var _m=String((typeof MY_URL!=='undefined')?MY_URL:'').match(/\/category\/([^\/?]+)/); _curCat=_m?_m[1]:''; }catch(e){}
    var _tabCat=''; try{ var _m2=_rgTab.match(/\/category\/([^\/?]+)/); _tabCat=_m2?_m2[1]:''; }catch(e){}
    if(!_curCat || !_tabCat || _curCat!==_tabCat){
      try{ putMyVar('rg_tab',''); putMyVar('rg_tabn',''); putMyVar('rg_page','1'); }catch(e){}
