        /* v107：顺手收「这一季」的官方季号/集数/封面/首集 vid —— 详情页要用它把站点没给的那几季
           补成季卡，并按官方 season_index 校正季号（plan/v 的 video_data 条目就带这些字段；
           content_type 1004=可播位(有 vid)、1007=推荐位(无 vid、episode_cnt=0)）。 */
        if (!seasons[id]) {
          seasons[id] = { sid:id, name:(nm ? String(nm) : ''), season:(parseInt(o.season_index, 10) || 0),
                          cnt:(parseInt(o.episode_cnt, 10) || 0), cover:String(o.cover || ''),
                          ct:(parseInt(o.content_type, 10) || 0) };
        } else if (!seasons[id].name && nm) { seasons[id].name = String(nm); }
