  } catch (e) { return null; }
}
/* v107：官方同系列集合里的「每一季」（官方季号/集数/封面/首集 vid），按官方季号升序 —— 详情页用它补站点的缺季。
   站点 /player 页的 videoList 会混入别的剧推荐、还常只给本剧 1~2 季（实测「大乾老六…再称王2」页只给第 2 季），
   而官方这个接口一次就把该剧所有季（含 season_index）给全了。 */
function hgsPlanSeasons(sid){
  try {
    var fam = hgsPlanFam(sid);
    if (!fam || !fam.seasons) return null;
    var out = [];
    for (var k in fam.seasons) {
      var s = fam.seasons[k];
      if (s && s.sid && s.season > 0) {
        out.push({ sid:String(s.sid), name:String(s.name || ''), season:(parseInt(s.season, 10) || 0),
                   cnt:(parseInt(s.cnt, 10) || 0), cover:String(s.cover || ''), ct:(parseInt(s.ct, 10) || 0) });
      }
    }
    out.sort(function (a, b) { return a.season - b.season; });
