}
function hgsFamRun(list, base, famIds){
  var out = [], fam = '', started = false, i, it, k, n = (list ? list.length : 0);
  /* ① 先定族：首个**带季号**的条目决定 C（中文季号）/ P（阿拉伯季号）；
       官方同系列命中的条目不参与定族（它们往往根本没季号） */
  for (i = 0; i < n; i++) {
    it = list[i] || {};
    if (famIds && famIds[String(it.sid || it.series_id || '')]) continue;
    if (hgsSeasonBase(it.name) !== base) continue;
    k = hgsFamKey(it.name, base);
    if (k === 'C' || k === 'P') { fam = k; break; }
  }
  /* ② 按合集原顺序收：官方同系列 → **无条件收**（v99：掀桌/掀桌2以身入局 这种「数字+副标题」
       命名，hgsSeasonBase 只认末尾的「N季 / 第N季」，剥不出季号 → 老逻辑把它整个丢掉）；
       名字同族 → 照老逻辑（异族/裸名后的条目截断） */
  for (i = 0; i < n; i++) {
    it = list[i] || {};
    if (famIds && famIds[String(it.sid || it.series_id || '')]) { it._fam = 1; out.push(it); continue; }
    if (!fam) continue;
    if (hgsSeasonBase(it.name) !== base) continue;
    k = hgsFamKey(it.name, base);
    if (k === '') {
      if (started) break;
      started = true; out.push(it); continue;
    }
    if (k !== fam) { if (started) break; continue; }
    started = true; out.push(it);
  }
  return hgsFamRenumber(out);
}
/* v99：只给**官方同系列放行进来**的条目（it._fam）按合集顺序顺延编季号 —— 它们的剧名剥不出
   季号（hgsSeasonNum 恒 0 → 会被当成第 1 季，与真第 1 季撞号，如「掀桌」/「掀桌2以身入局」）。
   名字本来就带季号的老条目一律不动（那些季号来自剧名，改了会串季）。 */
function hgsFamRenumber(list){
  var i, last = 0;
  for (i = 0; i < (list ? list.length : 0); i++) {
    var it = list[i] || {};
    var sn = parseInt(it.season, 10) || 0;
    if (it._fam && sn <= last) { sn = last + 1; it.season = sn; }
    if (sn > last) last = sn;
  }
  return list;
}
/* v34：播放页合集**偶发**返回「别的剧推荐列表」而不是本剧的季（实测同一 sid 6 次里 1 次），
   一次拿不到就重试，最多 tries 次，直到能切出本剧那一套合集为止。 */
function hgsPlayerFam(sid, base, tries){
  var n = tries || 3, k, lst, run, fam = hgsPlanFam(sid);
  var famIds = fam ? fam.ids : null;
  for (k = 0; k < n; k++) {
    try { lst = hgsPlayerSeasons(String(sid || '')); } catch (e) { lst = null; }
    if (!lst || !lst.length) continue;
    run = hgsFamRun(lst, base, famIds);
    if (run && run.length) return run;
  }
  return [];
}
function hgsSsrJSON(html){
  var raw = String(html||'');
  var i = raw.indexOf('_ROUTER_DATA');
  if (i < 0) return null;
  var eq = raw.indexOf('=', i), st = -1;
  for (var s = eq; s < raw.length; s++) { if (raw.charAt(s) === '{') { st = s; break; } }
  if (st < 0) return null;
  var dp = 0, ed = -1;
  for (var k = st; k < raw.length; k++) {
    var c = raw.charAt(k);
    if (c === '{') dp++; else if (c === '}') { dp--; if (dp === 0) { ed = k; break; } }
  }
  if (ed <= st) return null;
  try { return JSON.parse(raw.substring(st, ed + 1)); } catch (e) { return null; }
}
function hgsPick(ld, key){
  if (!ld) return null;
  for (var k in ld) { var w = (ld[k] || {}).content || ld[k]; if (w && w[key]) return w[key]; }
  return null;
}
/* 查同剧所有季：返回 [{season:季号, name:剧名, vids:[该季全部vid]}]（按季号升序）。
   - 剧名没有「第*季」时按第 1 季处理（剧名本身就是隐式第一季）
   - 站点搜索的 page 参数无效（1/2/3 页返回同一批 10 条），因此改用「多个关键词」
     扩展覆盖：先搜 base，发现不止一季再搜 base+第2季（统一阿拉伯季号），两次结果合并去重
     （实测 13 季的剧用这两次搜索即可全覆盖）
   - 当前季直接用页面已有数据补齐；结果按「剧名(去季号)」做 6 小时文件缓存 */
/* ---- 两段式整合的缓存与后台补齐 --------------------------------------
   缓存文件 hiker://files/cache/rg_seasons_<版本>_<剧名hash>.json，内容 {t, v, done}：
     done=0 → 只整合出「最小两季」（首屏秒开用），条目里附带后台线程在继续补
     done=1 → 全部季已整合好（下次进详情页直接全季秒开）
   每次进详情页都会自动做一次「增量检查」：① 最后一季有没有更新出新剧集
   ② 有没有出现新季（探 max+1 / max+2），命中就并进列表并回写缓存，无需任何按钮。 */
function hgsHash(base){
  var h = 0;
  for (var i = 0; i < base.length; i++) h = (h * 31 + base.charCodeAt(i)) % 100000007;
  return h;
}
function hgsCachePath(base){
  return 'hiker://files/cache/rg_seasons_' + HGS_CACHE_V + '_' + hgsHash(base) + '.json';
}
function hgsCachePick(base){
  if (!base) return null;
  try {
    var cs = readFile(hgsCachePath(base), 0);
    if (!cs) return null;
    var c = JSON.parse(String(cs));
    if (!c || (new Date().getTime() - (c.t || 0)) >= 6 * 3600 * 1000) return null;
    return { v: c.v || null, done: !!c.done, cast: c.cast || null };   /* v37：演员表也一起缓起来 */
  } catch (e) { return null; }
}
/* v37：写入时第 4 个参数是演员表；没传（或为空）就**沿用缓存里已有的那一份**，
   避免「补季线程写缓存」把刚存下来的演员表冲掉。 */
function hgsCacheWrite(base, v, done, cast){
  try {
    var cc = cast;
    if (!cc || !cc.length) {
      try {
        var old = readFile(hgsCachePath(base), 0);
        if (old) {
          var oj = JSON.parse(String(old));
          if (oj && oj.cast && oj.cast.length) cc = oj.cast;
          if ((!v || !v.length) && oj && oj.v && oj.v.length) v = oj.v;   /* 没给季数据也沿用旧的，避免写空 */
        }
      } catch (e0) {}
    }
    var o = { t: new Date().getTime(), v: v, done: done ? 1 : 0 };
    if (cc && cc.length) o.cast = cc;
    saveFile(hgsCachePath(base), JSON.stringify(o), 0);
  } catch (e) {}
}

/* 补全锁：同一部剧同一时间只允许一个补全在跑（后台自动补齐 vs 用户点「补全所有季」），
   避免重复请求与两边并发写缓存。用文件时间戳做标记，10 分钟自动过期（防进程被杀后锁不释放）。 */
function hgsBgFlag(base){ return 'hiker://files/_cache/rg_bg_' + hgsHash(base) + '.txt'; }
function hgsBgLock(base){
  try {
    var s = readFile(hgsBgFlag(base), 0);
    var t = s ? (parseInt(String(s), 10) || 0) : 0;
    if (t && (new Date().getTime() - t) < 10 * 60 * 1000) return false;   /* 还在跑 */
    saveFile(hgsBgFlag(base), String(new Date().getTime()), 0);
    return true;
  } catch (e) { return true; }
}
function hgsBgUnlock(base){ try { saveFile(hgsBgFlag(base), '0', 0); } catch (e) {} }
function hgsBgBusy(base){
  try {
    var s = readFile(hgsBgFlag(base), 0);
    var t = s ? (parseInt(String(s), 10) || 0) : 0;
    return !!(t && (new Date().getTime() - t) < 10 * 60 * 1000);
  } catch (e) { return false; }
}

/* v19/v69/v72：「补全所有季」的**后台执行体**（页面侧调用，见 hgsFillStart）——
   进页面看到 rg_fill 标记时调它：抢锁 → 起后台线程跑批探算法 hgsBtnFill（一次把漏掉的季与后续季探完）
   → 有新增季就写缓存并 refreshPage(false) 让本页显示出来。
   quiet=true：**自动补全静默**（用户要求「补全时静默不 toast」）——进详情页发现推荐页只覆盖了前 12 季时
   自动跑的那次不播报，只有用户点按钮（quiet 缺省）才播报「补全所有季中，请稍候 / 补全结束」。
   抢锁失败的重复点击直接返回（已有补全在跑），不会发双份请求。 */
function hgsBgFill(name, curSid, curVids, cover, intro, quiet){
  try {
    var base = hgsSeasonBase(name);
    if (!base) return false;
    if (!hgsBgLock(base)) return false;                    /* 已有补全在跑 → 不重复 */
    var th = new java.lang.Thread(function () {
      var _tb = new Date().getTime();
      try {
        var n = 0;
        try {
          n = hgsBtnFill({ b:base, n:String(name || ''), s:String(curSid || ''),
                           c:String(cover || ''), i:String(intro || '') }, null);
        } catch (e) {}
        try {
          saveFile('hiker://files/_cache/hgs_timing_bg.txt',
            '后台补全耗时=' + (new Date().getTime() - _tb) + 'ms  站点请求=' + HGS_REQ + '  新增季=' + n
            + (quiet ? '  quiet=1' : ''), 0);
        } catch (e) {}
        if (!quiet) { try { toast('补全结束'); } catch (e) {} }
        /* v22：补到内容就刷新本页 —— 否则自动补全出来的季与集不会显示（页面 setResult 后固化）。
           只在 n>0（确实补到新季）时刷新，避免无变化时反复刷新；刷新后缓存已 done=1，
           页面重跑规则时不会再启动后台补齐，因此不会循环。 */
        try { if (n > 0) refreshPage(false); } catch (e) {}
      } catch (e) {}
      hgsBgUnlock(base);
    });
    th.start();
    return true;
  } catch (e) { return false; }
}

/* 拉某季的剧集列表（series_id → vid_list），失败返回 null */
function hgsDetailVids(sid){
  try {
    HGS_REQ++;
    var dh = String(fetch(HGS_SITE + '/detail?series_id=' + sid, { headers:HGS_HDR, timeout:15000 }) || '');
    var dj = hgsSsrJSON(dh);
    var sd = dj && hgsPick(dj.loaderData, 'seriesDetail');
    if (sd && sd.vid_list && sd.vid_list.length) return sd.vid_list;
  } catch (e) {}
  return null;
}
/* 并发取一批 URL 的原始文本：Rhino 里用 java.lang.Thread + CountDownLatch，结果写
   Java String[]（Java 数组元素写安全）；线程里只做「取原始文本」，JSON 解析留在
   主线程，尽量避开 Rhino 多线程作用域问题。并发不可用时自动回退串行。
   这是全部提速的底座：批量搜索与逐季 detail 都走它。 */
function hgsFetchRawAll(urls){
  var n = urls ? urls.length : 0;
  var out = [];
  for (var i0 = 0; i0 < n; i0++) out.push('');
  if (!n) return out;
  var BATCH = 5, ok = true;
  for (var b = 0; b < n && ok; b += BATCH) {
    var cnt = Math.min(BATCH, n - b);
    var arr, latch;
    try {
      arr = java.lang.reflect.Array.newInstance(java.lang.String, cnt);
      latch = new java.util.concurrent.CountDownLatch(cnt);
    } catch (e) { ok = false; break; }
    for (var i = 0; i < cnt; i++) {
      (function (slot, u) {
        var t = new java.lang.Thread(function () {
          try {
            HGS_REQ++;
            arr[slot] = String(fetch(u, { headers:HGS_HDR, timeout:20000 }) || '');
          } catch (e) { try { arr[slot] = ''; } catch (e2) {} }
          finally { try { latch.countDown(); } catch (e3) {} }
        });
        try { t.start(); } catch (e) { try { latch.countDown(); } catch (e2) {} }
      })(i, String(urls[b + i] || ''));
    }
    try { latch.await(25, java.util.concurrent.TimeUnit.SECONDS); } catch (e) {}
    for (var s = 0; s < cnt; s++) out[b + s] = String(arr[s] || '');
  }
  if (!ok) {
    for (var q = 0; q < n; q++) {
      if (out[q]) continue;
      try { HGS_REQ++; out[q] = String(fetch(urls[q], { headers:HGS_HDR, timeout:20000 }) || ''); } catch (e) {}
    }
  }
  return out;
}
/* 并发拉多季 detail（逐季串行 12 次 → 3 轮）：线程只取原始文本，解析在主线程做；
   拿不到的季再串行补一次，保证不漏季。 */
function hgsDetailVidsAll(sids){
  var n = sids ? sids.length : 0;
  var out = [];
  if (!n) return out;
  var urls = [];
  for (var i0 = 0; i0 < n; i0++) { urls.push(HGS_SITE + '/detail?series_id=' + String(sids[i0] || '')); out.push(null); }
  var raws = hgsFetchRawAll(urls);
  for (var s = 0; s < n; s++) {
    if (!raws[s]) continue;
    try {
      var jj = hgsSsrJSON(raws[s]);
      var ssd = jj && hgsPick(jj.loaderData, 'seriesDetail');
      if (ssd && ssd.vid_list && ssd.vid_list.length) out[s] = ssd.vid_list;
    } catch (e) {}
  }
  for (var q = 0; q < n; q++) {
    if (out[q] && out[q].length) continue;
    out[q] = hgsDetailVids(sids[q]);
  }
  return out;
}

/* v20：同一季可能有多个重名候选（同名不同封面/不同简介的条目），按用户指定顺序择优：
   ① 封面图（series_cover）与「进入季」一致 → ② 详情描述（series_intro）一致 →
   ③ 名字贴近（标题恰为 base / base第N季 / base+N季）→ ④ 都没有就取首个。 */
function hgsPickCands(list, fp, base, sn){
  if (!list || !list.length) return '';
  if (list.length === 1) return String(list[0].sid || '');
  var cov = (fp && fp.c) ? String(fp.c) : '';
  var itr = (fp && fp.i) ? String(fp.i) : '';
  var j;
  if (cov) { for (j = 0; j < list.length; j++) if (String(list[j].cover || '') === cov) return String(list[j].sid || ''); }
  if (itr) { for (j = 0; j < list.length; j++) if (String(list[j].intro || '') === itr) return String(list[j].sid || ''); }
  if (base) {
    for (j = 0; j < list.length; j++) {
      var tn = String(list[j].title || '');
      if (tn === base || tn === base + '第' + sn + '季' || tn === base + sn + '季') return String(list[j].sid || '');
    }
  }
  return String(list[0].sid || '');
}
/* v20：描述「一致」判定 —— 不只看完全相同：
   先把空白与常见标点全部去掉（全半角标点都剥）、截前 60 字，再看
   ① 归一化后完全相同，或 ② 前 min(长度) 个字符完全一致且长度 ≥ 16。
   站点同一部剧的不同季/不同上架，简介常是同一段（可能尾部被截断或加料），
   仅「严格相等」会漏判（实测烬九州「第二季」与「首季」简介一字不差、但候选间长度不同）。 */
function hgsNormIntro(s){
  return String(s || '')
    .replace(/[\s\u3000]+/g, '')
    .replace(/[，。！？、；：""''（）《》…—·,.!?;:"'()<>\[\]|\/\\~`]+/g, '')
    .slice(0, 60);
}
function hgsIntroSame(a, b){
  var ia = String(a || ''), ib = String(b || '');
  if (ia && ib && ia === ib) return true;
  var na = hgsNormIntro(ia), nb = hgsNormIntro(ib);
  if (!na || !nb) return false;
  if (na === nb) return true;
  var n = Math.min(na.length, nb.length);
