   而注册要走 log.snssdk.com + reading/crypt/registerkey 两步网络请求；一旦失败，
   原来的写法是直接抛异常被上层 try/catch 吞掉，页面只剩一句「数据为空」，完全看不出原因。
   现在：注册失败就退回内置设备（书城/目录这类不校验注册的接口仍可用），并把错误文本交给页面显示。 */
function hgFqDev() {
  try {
    if (FQ && typeof FQ.bestDevice === 'function') {
      var r = FQ.bestDevice();
      return { dev: r.dev, err: r.err, src: r.src };
    }
  } catch (e) {}
  /* 老库兼容：云端逻辑库会热更到旧规则上，而旧规则内联的 FQ 库可能还没有 bestDevice ——
     这里退回「注册 + 内置兜底设备」，不让页面因为缺一个函数就整页空掉。 */
  try { return { dev: FQ.ensureDevice(), err: '', src: 'legacy' }; }
  catch (e2) {
    var d = null, _m2 = '';
    try { _m2 = String(e2.message || e2); } catch (e3) { _m2 = String(e2); }
    try { d = FQ.fallbackDevice ? FQ.fallbackDevice() : null; } catch (e4) { d = null; }
    return { dev: d, err: _m2, src: d ? 'legacy-fb' : 'none' };
  }
}
/* 设备/库不可用时统一渲染一张「说清楚原因」的卡片（点它复制错误文本，方便反馈） */
function hgFqErrCards(dev, err, what) {
  var out = [];
  out.push({ title: '⚠️ ' + what + '暂时取不到', col_type: 'text_1' });
  if (err) { out.push({ title: '原因：' + err, col_type: 'text_1' }); }
  out.push({ title: (dev ? '已退回内置设备，' : '番茄库未生效，') + '下拉重试；仍有问题请截图这一段反馈',
             col_type: 'text_1' });
  return out;
}

/* 章节点击（lazyRule）：取该话正文 → picInfos + encrypt_key → 拼 pics:// 返回。
   点击上下文与页面上下文不共享作用域，所以这里先 readFile('rglib.js') 再 eval ——
   跟项目里既有的播放 lazyRule 取库方式一致。 */
function hgComicChapterJs(itemId) {
  var _i = String(itemId || '').replace(/[^0-9]/g, '');
  /* v92 修正：同样必须包 IIFE —— 顶层 return 会被 Rhino 判 SyntaxError(msg.bad.return＝「返回的值无效」)，
     漫画详情页点章节就是死在这一点上（「未知链接：error:返回的值无效 (JSEngine#14)」）。 */
  return "(function(){"
    + "var _s='';"
    + "try{_s=readFile('rglib.js',0);}catch(e){}"
    + "if(!_s){try{_s=getMyVar('rglib');}catch(e){}}"
    + "if(!_s){try{_s=getVar('rglib');}catch(e){}}"
    + "if(_s){eval(_s);}"
    /* v86：设备统一走 FQ.bestDevice —— 优先本机注册，注册失败/缺密钥时退回**预置设备**（功能完整） */
    + "var _r=null;"
    + "try{_r=FQ.bestDevice();}catch(_x){_r=null;}"
    + "var _d=_r?_r.dev:null;"
    + "var _e=_r?String(_r.err||''):'番茄库未生效';"
    + "if(!_d){try{toast('番茄设备不可用'+( _e?('：'+_e):'' ));}catch(_t0){}return 'hiker://empty';}"
    + "var _t='';"
    + "try{_t=String(FQ.content('" + _i + "',_d.device_id,_d.secret_key)||'');}catch(_q){_t='';}"
    + "if(!_t){try{toast('这一话取不到正文'+( _e?('（'+_e+'）'):'' ));}catch(_t0){}return 'hiker://empty';}"
    + "var _j=JSON.parse(_t.slice(_t.indexOf('{'),_t.lastIndexOf('}')+1));"
    + "var _kk=String(_j.encrypt_key||'');"
    + "var _p=_j.picInfos||[];"
    + "var _o=[];"
    + "for(var _x=0;_x<_p.length;_x++){var _u=String(_p[_x].picUrl||'');if(_u){_o.push(_u+'@js='+hgComicImgJs(_kk));}}"
    + "if(!_o.length){try{toast('这一话取不到图片');}catch(_t0){}return 'hiker://empty';}"
    + "return 'pics://'+_o.join(String.fromCharCode(38,38));"
    + "})()";
}

/* v37/v50：**演员表** —— 点名字看 TA 的作品：把「演员id|名字」写进文件状态
   （rg_act_<series_id>.txt，绑定当前剧）后原地刷新本页，顶部出现「TA 的作品」+「返回本剧」。 */
var HG_ACT_STATE = 'hiker://files/_cache/rg_act_';
function hgActStatePath(sid){ return HG_ACT_STATE + String(sid || '0') + '.txt'; }
function hgActState(sid){
