    if (!s) return null;
    var p = s.split('|');
    if (!p[0]) return null;
    return { cid:String(p[0]).replace(/[\s\u3000]/g, ''), name:String(p[1] || '') };
  } catch (e) { return null; }
}
function hgActClick(sid, cid, nm){
  try {
