}
/* v38：**演员表改成一行横滑**（头像缩小，可以向右拉）——
   海阔的 `scroll_button` 实测就是「一行横向滚动容器」（ScrollButtonHolder =
   HorizontalScrollView + LinearLayout，还有个「展开」按钮），所以整张演员表只占一行；
   每张卡：圆形小头像 + 昵称（角色名放 desc）。点名字仍是「看 TA 的作品」（原地刷新）。 */
function hgCastRows(cast, sid){
  var out = [];
  if (!cast || !cast.length) return out;
  /* v52：用户要求去掉「演员表（点名字看 TA 的作品）」这一行 —— 只保留名字卡片那一行。 */
  for (var i = 0; i < cast.length; i++) {
    var c = cast[i] || {};
    if (!c.name) continue;
    /* v56：**和「返回本剧」按钮同一种做法** —— 用 flex_button（流式按钮行）而不是 scroll_button：
       反编译里 flex_button 的条目自带灰色圆角底 + 行内间距，且**不会被上下相邻行裁掉**；
       scroll_button 是 HorizontalScrollView 行，紧贴上一行时顶部会被裁（用户实测反馈）。
       flex_button 由海阔自动聚合：连着 push 多个就合到同一行、放不下自动换行。 */
    var it = { title:String(c.name), desc:String(c.role || ''), col_type:'flex_button',
               url:hgActClick(sid, c.cid, c.name) };
    out.push(it);
  }
  return out;
