/* v61：**点季标题 → 原地折叠/展开这一季的选集格子**（用户要求：不刷新详情页、原地折叠，
   方便一路往下翻找别的季）。海阔自带一套「动态刷新界面元素」接口（见 assets/help_js.json 里
   同名那一节），它们都在**当前列表上原地增删、不 refreshPage**，正好够用：
     · findItemsByCls(cls)   取这一季此刻还在界面上的条目（顺带当「现在是展开还是折叠」的判据）
     · deleteItemByCls(cls)  按 cls 原地删掉这一季的格子
     · addItemAfter(id,rows) 把格子原地插回季标题（id 是季标题的 extra.id）后面
     · updateItem(id,{title}) 只改标题（加 ▶/▼ 折叠标记）
   折叠前先把这一季的整条 JSON（findItemsByCls 的返回值）存进 _cache 快照，展开时 readFile 取回来。
   快照放 _cache/ 是故意的：海阔会把 _cache 里超过 30 分钟的文件自动清掉，而每次进详情页都会重新
   渲染（= 全展开、状态归零），所以不会出现「快照还在、界面已经重来」那种对不上的情况。
   cls 只加在这一季的格子上（'rgep rgse<季序号>'）：hiker 按 cls 删除是空格分词匹配，
   'rgse2' 正好只命中第 2 季；不写 'playlist'，免得打乱 hiker 自己按「连续同 col_type」分选集组的逻辑
   （跨季连播靠的就是那个）。 */
function hgFoldClick(stId, cls, title, foldFile, stFile, tok){
  try {
    if (typeof $ !== 'function' || !stId) return '';
    var u = $('hiker://empty').lazyRule(function (p) {
      try {
        /* v63：**别拿 findItemsByCls 判断「现在是展开还是折叠」** —— JSEngine._findItemsByCls 是同步
           等 EventBus 回复的（countDownLatch.await(3L, SECONDS)），而 ArticleListFragment.findItems
           只在**查得到条目**时才 countDown；折叠状态下这一季的格子已经不在列表里 → 查不到 → 不唤醒 →
           白等满 3 秒。这正是「折叠秒开、展开卡 3 秒」的原因。
           改成读一个「本次渲染标记」小文件（几字节，纯读文件、瞬回）：
             · 每次进详情页渲染时把当前时间戳当 tok，塞进标题的 lazyRule 参数；
             · 折叠时把 tok 落盘；展开时清空 ⇒ 文件内容 === tok 才是「已折叠」。
           页面重渲染 = 新 tok ⇒ 旧标记自动失效（全展开状态归零），不需要每次渲染都写文件。
           只有**折叠那一步**才调 findItemsByCls（那时格子还在、能命中、很快），而且必须调：
           它是唯一能把这一季条目（含超长的播放 url）整体抓下来的接口。
         ⚠ 另外两个实测坑（都在这一块踩过，别改回去）：
           ① findItemsByCls 返回的是**桥接过来的原生对象数组**，不是 JSON 字符串 ——
              String() 出来是「[object Object],…」，JSON.parse 必崩 → 会被误判成「已折叠」，
              接着去展开、快照又是空的 → 弹「选集已过期」。所以要用 JSON.stringify。
           ② findItemsByCls 拿回来的条目是 hiker 自己那套键名（`type` / `pic`），而
              addItemAfter 走的是 JSEngine.convertToArticleList —— 那边**只认 `col_type`**（还认 img/pic/
              pic_url）。直接回插会丢掉 col_type → 选集退回默认大格子（实测：折叠后再展开变成一行 3 个）。
              所以回插前必须先把条目**规范化成规则侧键名**。 */
        var folded = false;
        try { folded = (String(readFile(String(p.stf), 0) || '') === String(p.tok)); } catch (e0) { folded = false; }
        if (!folded) {                               /* 展开中 → 折叠 */
          var rowsAll = [];
          try {
            var arr = findItemsByCls(String(p.cls));
            for (var qi = 0; arr && qi < arr.length; qi++) {
              var it = arr[qi] || {};
              if (!it.title) continue;
              rowsAll.push({ title:String(it.title),
                             col_type:String(it.col_type || it.type || 'text_5'),
                             url:String(it.url || ''),
                             desc:String(it.desc == null ? '' : it.desc),
                             extra:(it.extra == null ? { id:String(it.id || ''), cls:String(p.cls) } : it.extra) });
            }
          } catch (e9) { rowsAll = []; }
          if (rowsAll.length) {
            try { saveFile(String(p.f), JSON.stringify(rowsAll), 0); } catch (e1) {}
            try { deleteItemByCls(String(p.cls)); } catch (e2) {}
            try { updateItem(String(p.st), { title:'▶ ' + String(p.title) }); } catch (e3) {}
            try { saveFile(String(p.stf), String(p.tok), 0); } catch (e1b) {}
          } else {
            try { toast('这一季的选集已过期，退出重进本剧即可'); } catch (e1c) {}
          }
        } else {                                     /* 已折叠 → 展开：读快照原地插回 */
          var rows = [], rr = '';
          try { rr = String(readFile(String(p.f), 0) || ''); } catch (e4) { rr = 'ERR:' + e4; }
          try { rows = JSON.parse(rr) || []; } catch (e4b) { rows = []; }
          try { updateItem(String(p.st), { title:String(p.title) }); } catch (e5) {}
          if (rows.length) {
            try { addItemAfter(String(p.st), rows); saveFile(String(p.stf), '', 0); } catch (e6) {}
          } else {
            try { toast('这一季的选集已过期，退出重进本剧即可'); } catch (e7) {}
          }
        }
      } catch (e) {}
      return 'hiker://empty';
    }, { st:stId, cls:cls, title:title, f:foldFile, stf:stFile, tok:tok });
    /* v66：**必须带上 #ignoreVideo=true# 这个 tag** —— 这是修「跨季连播失效」的关键：
       反编译 ArticleListFragment.getChapters()（组播放器章节链）里，往前/往后扫的循环是
         if (!isEmpty(url) && !url.contains("ignoreVideo") && !url.contains("@rule=") ...) {
             if (!zIsPlayList && !equals(type, type_i)) break;   // ← 类型不同才 break
             ...收进章节链...
         }
       季标题是 text_1、选集格子是 text_5：v60 之前标题**没有 url**，`!isEmpty(url)` 为假 → 整条被跳过、
       不 break → 链子能继续跨到下一季的格子上（跨季连播就是这么来的）；v61 给标题加了折叠
       url 之后它就有了 url → 走到类型判断 → 类型不同 → **break** → 链子在季边界断掉（用户报的失效）。
       带上 ignoreVideo 这个 tag（url.contains("ignoreVideo") 为真）→ 又会被整条跳过、不再 break，
       跨季连播恢复；而这个 tag 只是告诉海阔「别把它当视频」，点击照样走 @lazyRule（tag 解析前会被 clearTag）。 */
    return (u && u.replace) ? String(u).replace('hiker://empty', 'hiker://empty#ignoreVideo=true#') : u;
  } catch (e) { return ''; }
}
/* v69：**「折叠所有季」按钮**（放在「补全所有季」后面）—— 点一下把所有季的格子原地收起来、只留季标题，
   再点一下全部展开。跟单季折叠同一套接口（deleteItemByCls / updateItem / addItemAfter / findItemsByCls），
   也共用同一批文件与标记：
     · 快照  rg_fold_<剧id>_<季序>.json       （格子原样，展开时插回）
     · 标记  rg_foldst_<剧id>_<季序>.txt      （内容 = 本次渲染 tok ⇒ 该季算「已折叠」）
     · 按钮态 rg_foldall_<剧id>.txt           （内容 = 本次渲染 tok ⇒ 整页算「已折叠」）
   所以「先折叠所有季、再点某一季标题展开」「先单独折某一季、再折叠所有季」都能对得上。
   参数只有 4 个短串（按钮 id / 剧 id / tok / 状态文件），季序号是点击时从 extra.id 现解析的
   —— URL 不随季数膨胀（32 季也不会撑爆 lazyRule）。 */
function hgFoldAllClick(btnId, sid, tok, stf){
  try {
    if (typeof $ !== 'function' || !btnId) return '';
    var u = $('hiker://empty').lazyRule(function (p) {
      var S = String(p.s || ''), TOK = String(p.t || ''), CACHE = 'hiker://files/_cache/';
      try {
        var folded = false;
        try { folded = (String(readFile(String(p.f), 0) || '') === TOK); } catch (e0) {}
        /* 现取整个季区（标题 + 格子都带 cls 'rgsec'）；季序号从 extra.id 解析：
           rgst<剧id>_<季序> / rgep<剧id>_<季序>_<集序> —— 标题顺序就是季序升序 */
        var all = [];
        try { all = findItemsByCls('rgsec') || []; } catch (e1) { all = []; }
        function exOf(it){
          var ex = it && it.extra;
          if (ex && typeof ex === 'string') { try { ex = JSON.parse(ex); } catch (e) { ex = null; } }
          return (ex && typeof ex === 'object') ? ex : {};
        }
        function toRows(arr){
          var rows = [];
          for (var i = 0; arr && i < arr.length; i++) {
            var it = arr[i]; if (!it) continue;
            /* v62 的两个坑照旧：键名要规范化回 col_type（不然回插会变成大格子）、extra 要保原样 */
            rows.push({ title:String(it.title || ''),
                        col_type:String(it.col_type || it.type || 'text_5'),
                        url:String(it.url || ''), desc:String(it.desc == null ? '' : it.desc),
                        extra:exOf(it) });
          }
          return rows;
        }
        var seas = [], seen = {}, i, m;
        for (i = 0; i < all.length; i++) {
          m = String(exOf(all[i]).id || all[i].id || '').match(/^rgst[0-9]+_([0-9]+)$/);
          if (!m || seen[m[1]]) continue;
          seen[m[1]] = 1;
          var t = String(all[i].title || '');
          seas.push({ si:m[1], st:String(exOf(all[i]).id || ''), cls:'rgse' + m[1],
                      title:(t.indexOf('▶ ') === 0) ? t.slice(2) : t });
        }
        if (!seas.length) { try { toast('没找到季标题，退出重进本剧即可'); } catch (e2) {} return 'hiker://empty'; }
        for (var k = 0; k < seas.length; k++) {
          var s = seas[k];
          if (!folded) {                       /* 折叠：抓格子的快照 → 删格子 → 标题加 ▶ → 落本季标记 */
            var cells = [];
            for (i = 0; i < all.length; i++) {
              if (String(exOf(all[i]).id || '').indexOf('rgep' + S + '_' + s.si + '_') === 0) cells.push(all[i]);
            }
            var rows2 = toRows(cells);
            if (!rows2.length) continue;       /* 本来就没格子（这一季早已单独折叠）→ 只可能缺快照，见展开分支 */
            try { saveFile(CACHE + 'rg_fold_' + S + '_' + s.si + '.json', JSON.stringify(rows2), 0); } catch (e4) {}
            try { deleteItemByCls(s.cls); } catch (e5) {}
            try { updateItem(s.st, { title:'▶ ' + s.title }); } catch (e6) {}
            try { saveFile(CACHE + 'rg_foldst_' + S + '_' + s.si + '.txt', TOK, 0); } catch (e7) {}
          } else {                             /* 展开：读快照插回 + 清本季标记（快照缺失才退回整页重渲染） */
            var rows3 = [];
            try { rows3 = JSON.parse(String(readFile(CACHE + 'rg_fold_' + S + '_' + s.si + '.json', 0) || '[]')) || []; } catch (e8) { rows3 = []; }
            try { updateItem(s.st, { title:s.title }); } catch (e9) {}
            if (!rows3.length) { try { refreshPage(false); } catch (eC) {} return 'hiker://empty'; }
            try { addItemAfter(s.st, rows3); } catch (eA) {}
            try { saveFile(CACHE + 'rg_foldst_' + S + '_' + s.si + '.txt', '', 0); } catch (eB) {}
          }
        }
        try { saveFile(String(p.f), folded ? '' : TOK, 0); } catch (eD) {}
        /* 按钮自己改文案（下次进本页重渲染又会回到「折叠所有季」，因为页面标记已失效） */
        try { updateItem(String(p.b), { title:(folded ? '折叠所有季' : '展开所有季') }); } catch (eE) {}
      } catch (eZ) {}
      return 'hiker://empty';
    }, { b:btnId, s:sid, t:tok, f:stf });
    return (u && u.replace) ? String(u).replace('hiker://empty', 'hiker://empty#ignoreVideo=true#') : u;
  } catch (e) { return ''; }
}

/* v65：**详情页渲染整段搬进逻辑库**（用户要求：以后改详情页也不用再手动粘贴导入）——
   两个模板（detail_find_rule / pages[0].rule）里那段渲染是逐字节一样的，这里合并成一个函数。
   拆库（v70）后这一段在 DETAIL_LIB 里；它同时(1)内联进那两条规则（离线/首次安装也有兜底）
   (2)被云端库顶层 eval 覆盖 ⇒ 改详情页排版、增删行、按钮，只推 hongguo_lib.js 就生效。
   调用方只传 d（结果数组）、sd（seriesDetail）、PLAY（播放代码）。 */
function hgDetailRender(d, sd, PLAY){
    /* v68：计时起点 —— 从这里往下就是「首屏同步段」（只用本地数据渲染、一个网络请求都不发），
