      var s = fam.seasons[k];
      if (s && s.sid && s.season > 0) {
        out.push({ sid:String(s.sid), name:String(s.name || ''), season:(parseInt(s.season, 10) || 0),
                   cnt:(parseInt(s.cnt, 10) || 0), cover:String(s.cover || ''), ct:(parseInt(s.ct, 10) || 0) });
