}
function hgsCachePick(base){
  if (!base) return null;
  try {
    var cs = readFile(hgsCachePath(base), 0);
    if (!cs) return null;
    var c = JSON.parse(String(cs));
    if (!c || (new Date().getTime() - (c.t || 0)) >= 6 * 3600 * 1000) return null;
    return { v: c.v || null, done: !!c.done, cast: c.cast || null };   /* v37：演员表也一起缓起来 */
  } catch (e) { return null; }
}
/* v37：写入时第 4 个参数是演员表；没传（或为空）就**沿用缓存里已有的那一份**，
   避免「补季线程写缓存」把刚存下来的演员表冲掉。 */
