          if (oj && oj.cast && oj.cast.length) cc = oj.cast;
          if ((!v || !v.length) && oj && oj.v && oj.v.length) v = oj.v;   /* 没给季数据也沿用旧的，避免写空 */
        }
      } catch (e0) {}
    }
