  try {
    var s = readFile(hgsBgFlag(base), 0);
    var t = s ? (parseInt(String(s), 10) || 0) : 0;
    return !!(t && (new Date().getTime() - t) < 10 * 60 * 1000);
  } catch (e) { return false; }
