function hgsBgFill(name, curSid, curVids, cover, intro, quiet){
  try {
    var base = hgsSeasonBase(name);
    if (!base) return false;
    if (!hgsBgLock(base)) return false;                    /* 已有补全在跑 → 不重复 */
    var th = new java.lang.Thread(function () {
      var _tb = new Date().getTime();
      try {
        var n = 0;
        try {
          n = hgsBtnFill({ b:base, n:String(name || ''), s:String(curSid || ''),
                           c:String(cover || ''), i:String(intro || '') }, null);
        } catch (e) {}
        try {
          saveFile('hiker://files/_cache/hgs_timing_bg.txt',
            '后台补全耗时=' + (new Date().getTime() - _tb) + 'ms  站点请求=' + HGS_REQ + '  新增季=' + n
            + (quiet ? '  quiet=1' : ''), 0);
        } catch (e) {}
        if (!quiet) { try { toast('补全结束'); } catch (e) {} }
        /* v22：补到内容就刷新本页 —— 否则自动补全出来的季与集不会显示（页面 setResult 后固化）。
           只在 n>0（确实补到新季）时刷新，避免无变化时反复刷新；刷新后缓存已 done=1，
           页面重跑规则时不会再启动后台补齐，因此不会循环。 */
        try { if (n > 0) refreshPage(false); } catch (e) {}
      } catch (e) {}
      hgsBgUnlock(base);
    });
    th.start();
    return true;
  } catch (e) { return false; }
}

/* 拉某季的剧集列表（series_id → vid_list），失败返回 null */
function hgsDetailVids(sid){
  try {
    HGS_REQ++;
    var dh = String(fetch(HGS_SITE + '/detail?series_id=' + sid, { headers:HGS_HDR, timeout:15000 }) || '');
    var dj = hgsSsrJSON(dh);
    var sd = dj && hgsPick(dj.loaderData, 'seriesDetail');
