   主线程，尽量避开 Rhino 多线程作用域问题。并发不可用时自动回退串行。
   这是全部提速的底座：批量搜索与逐季 detail 都走它。 */
function hgsFetchRawAll(urls){
  var n = urls ? urls.length : 0;
  var out = [];
  for (var i0 = 0; i0 < n; i0++) out.push('');
  if (!n) return out;
