  var out = [];
  if (!n) return out;
  var urls = [];
  for (var i0 = 0; i0 < n; i0++) { urls.push(HGS_SITE + '/detail?series_id=' + String(sids[i0] || '')); out.push(null); }
  var raws = hgsFetchRawAll(urls);
  for (var s = 0; s < n; s++) {
    if (!raws[s]) continue;
    try {
      var jj = hgsSsrJSON(raws[s]);
      var ssd = jj && hgsPick(jj.loaderData, 'seriesDetail');
      if (ssd && ssd.vid_list && ssd.vid_list.length) out[s] = ssd.vid_list;
    } catch (e) {}
  }
  for (var q = 0; q < n; q++) {
    if (out[q] && out[q].length) continue;
