  d.push(hgBtn('全部', 'scroll_button', all, '全部', HG_TAB ? (HG_TAB === all) : true));
  for (var i = 0; i < sel.length; i++) {
    var tu = HG_SITE + '/category/' + cat + '/' + sel[i].selector_item_id;
    var nm = sel[i].show_name;
    d.push(hgBtn(nm, 'scroll_button', tu, nm, HG_TAB === tu));
