   分类页是 loaderData[x].recommendList，搜索页是 loaderData[x].searchList，
   剧集页是 loaderData[x].seriesDetail，所以 content 要下钻一层。 */
function hgDig(ld){
  var o = { search: null, rec: null, rank: null, detail: null, sel: null, cat: null };
  for (var k in ld) {
    var v = ld[k];
    if (!v || typeof v !== 'object') continue;
    var w = (v.content && typeof v.content === 'object') ? v.content : v;
    if (w.searchList) o.search = w.searchList;
    if (w.recommendList) o.rec = w.recommendList;
    if (w.rankList) o.rank = w.rankList;
    if (v.seriesDetail) o.detail = v.seriesDetail;
    if (w.selectorList && w.selectorList.length) o.sel = w.selectorList[0].items || [];
    if (v.categoryRoute) o.cat = v.categoryRoute.contentType;
    else if (w.categoryRoute) o.cat = w.categoryRoute.contentType;
  }
  return o;
}

