/* 图片后处理器（挂在 pics:// 条目的 @js= 后缀上）：
   海阔把下到的密文以 input（InputStream）传进来，这里用 Java 原生 AES-GCM 解密，
   再返回一个新的 InputStream —— Glide 的 DataFetcher 只认 InputStream，字符串会崩。
   · 图布局与 fqapp 一致：iv=前 12 字节，密文居中，tag=末 16 字节；Java GCM 要「密文||tag」。
   · 400KB 的图在 Rhino 里跑纯 JS GHASH 太慢，所以设备上走 Java Cipher；
     纯 JS 版（FQ.gcmDecrypt）已在 Node 对拍台验证通过，留作备查。
   · ⚠ 这段会被塞进 pics:// 条目里（海阔按 && 切分），所以**不得出现 && 字面量**。 */
function hgComicImgJs(keyHex) {
  var _k = String(keyHex || '').replace(/[^0-9a-fA-F]/g, '');
  /* v92 关键修正：**整段必须包在 IIFE 里**。
     海阔 evalJS 把规则代码包成 `try{ …代码… }catch(e){setError(e);}`（JSEngine.getReplaceJS），
     代码仍在**顶层作用域**，所以顶层 `return` 会命中 Rhino 的 SyntaxError `msg.bad.return`
     —— 中文资源包里的原文就是「返回的值无效」，在海阔界面表现为
     「未知链接：error:返回的值无效 (JSEngine#14)」。
     （项目里能跑的播放 lazyRule 早就是 (function(){…})() 写法，只有漫画这两段漏了。）
     改法：整段塞进 IIFE，末句 `})()` 的取值即 IIFE 的返回值，海阔照样拿到。 */
  return '(function(){'
    + 'var _k="' + _k + '";'
    + 'var _JA=Packages.java.lang.reflect.Array;var _JB=Packages.java.lang.Byte.TYPE;'
    + 'var _b=[],_f=_JA.newInstance(_JB,65536),_n;'
    + 'while((_n=input.read(_f))>0){for(var _i=0;_i<_n;_i++){_b.push(_f[_i]&255);}}'
    + 'var _jv=function(_a){var _r=_JA.newInstance(_JB,_a.length);for(var _q=0;_q<_a.length;_q++){var _v=_a[_q]&255;_r[_q]=_v>127?(_v-256):_v;}return _r;};'
    + 'var _kb=[];for(var _i=0;_i<_k.length;_i+=2){_kb.push(parseInt(_k.substr(_i,2),16));}'
    + 'var _c=Packages.javax.crypto.Cipher.getInstance("AES/GCM/NoPadding");'
    + '_c.init(2,new Packages.javax.crypto.spec.SecretKeySpec(_jv(_kb),"AES"),new Packages.javax.crypto.spec.GCMParameterSpec(128,_jv(_b.slice(0,12))));'
    + 'return new Packages.java.io.ByteArrayInputStream(_c.doFinal(_jv(_b.slice(12))));'
    + '})()';
}

