     布局 item_article_header_item；选中 = 背景 drawable tab_item_selected
     + 文字色 R.color.yellowAction（跟随主题色）；未选中 = tab_item_default
     + R.color.black_666；padding 10/3dp、项间距 5dp。
   规则侧只能给纯色 backgroundColor（drawable 与 textColor 都指定不了），
   所以命中项用浅绿纯色近似；文字色保持布局默认（不再加 ““ ”” 标记，避免被
   setSpanText 转成内置的红/橙字）。 */
function hgBtn(title, colType, u, n, hit){
  var extra = hit ? { backgroundColor:'#DCF2E2' } : {};
  if (HG_CAN_TAB) {
    return { title:title, col_type:colType, url:hgTabClick(u,n), extra:extra };
  }
  return { title:title, col_type:colType, url:u + '?page=1' + HG_HDR, extra:extra };
}

/* 搜索框：onChange 是海阔官方支持的输入监听；点确定执行 url 里的 js（input 即输入值）。
   这里不跳新页面，而是写状态 + refreshPage，结果原地出现在下方。 */
/* v43：**搜索框和「清理」按钮做成同一行**（用户要求：搜索框缩小点、后面补上按钮）。
   海阔的输入行布局（反编译 res/layout/item_input.xml）本身就是
   「一个黑边框（check_bg_white：2dp 描边 + 8dp 圆角）里 = 输入框 + 细分隔线 + 右侧一个按钮」，
   按钮文字取自 item.title，且**只有一个按钮位**（只有一个 search TextView，且是
   `setText(title)` 纯文本、不吃 HTML）——所以「搜索」和「清理」只能共用这一个按钮：
   v44 起按钮文字写成 **「搜索/清理」**（用户要求两个字样一起显示），
   输入区自然被压窄，按钮就贴在它右边、同一个黑框里（= 用户要的「搜索框缩小点，后面补上按钮」）。
   另外反编译 ArticleListAdapter.bindForInputHolder 确认：**键盘回车/确定 = 点这个按钮**
   （ViewTool.setOnEnterClickListener → search.performClick()），所以 url 必须按内容分支：
     · 输入框有字 → 当搜索用（写 rg_kw + refreshPage，结果原地刷在下方）
     · 输入框为空 → 当清理用（readFile+eval 装回清缓存库，全清一次、报数、原地刷新）
   即「打字后回车/点按钮 = 搜索」「清空后点按钮 = 清理」，两个功能都在同一行同一条黑框内，
   也没有 icon_1_search 那个多余的扫描图标。 */
function hgSearchInput(){
  /* v74：**清理标记在逻辑库里处理**（跟 v71 的「后台补季/补全」一样，不再依赖模板正文那段）——
     用户点「搜索/清理」而输入为空时，按钮只写 rg_gc 标记 + 刷新本页；本函数首页/搜索页每次渲染都会跑到，
     在这里读到标记就直接跑 hgCacheGc()（它就在本库里）并把结果 toast 出来。
     放在库里 ⇒ 老版本导入的规则只要库热更上来，清理按钮照样能用。模板末尾那段保留着当兜底：
     标记已经被这里清掉 = 空操作，不会清两遍。 */
  try {
    if (String(getMyVar('rg_gc','')) === '1') {
      putMyVar('rg_gc', '');
      var _rgv = { n:0, mb:0 };
      try { _rgv = hgCacheGc(); } catch (e0) {}
      /* v75：**播报挪到渲染之后再发** —— 上面这步是在「本页正在重建列表」的过程里跑的，
         这时候直接 toast 会被海阔吞掉（用户反馈「清理完成后没有 toast 内容」）。
         放到后台线程里等 400ms（本页 setResult 早就完成了）再播报，跟「补全结束」同一套做法。 */
      try {
        var _rgmsg = '已清理 ' + _rgv.n + ' 个文件，释放 ' + _rgv.mb + 'MB';
        if (typeof java !== 'undefined' && java && java.lang && java.lang.Thread) {
          var _rgth = new java.lang.Thread(function () {
            try { java.lang.Thread.sleep(400); } catch (eS) {}
            try { toast(_rgmsg); } catch (eT) {}
          });
          _rgth.start();
        } else { toast(_rgmsg); }
      } catch (e1) {}
    }
  } catch (eG) {}
  return {
    col_type:'input', title:'搜索/清理', desc:'输入片名/演员',
    extra:{
      onChange:"try{ putMyVar('rg_kw',String(input||'')); putMyVar('rg_page','1'); }catch(e){}",
      defaultValue: HG_KW || ''
    },
    url: "(function(){ var kw=''; try{ kw=String((typeof input!=='undefined'&&input)||'').replace(/^\\s+|\\s+$/g,''); }catch(e0){}"
       + " if(kw){"
       +   " try{ putMyVar('rg_kw',kw); putMyVar('rg_page','1'); }catch(e){}"
       +   " try{ refreshPage(true); }catch(e){}"
       + " } else {"
       /* v70：清理由**页面自己**跑（hgCacheGc 就在 PAGE_LIB 里）：这里只写标记 + 刷新，
          不再需要把整套清理源码落成 rg_gc.js 给点击上下文 eval。 */
       +   " try{ putMyVar('rg_gc','1'); refreshPage(false); }catch(e){}"
       + " }"
       + " return 'hiker://empty'; })()"
  };
}
/* v109：**登录功能已按用户要求整体移除** —— 原 v104~v108 的「账号登录面板」
   （凭证登录 / 手机号+验证码 / 网页登录取凭证 / 退出登录）与搜索框的登录入口一并删掉；
   rglib 里对应的账号 API（accountGet / accountSave / accountClear / withAcct / accountVerify /
   sendLoginCode / smsLoginCheck / userInfo / rgQs）也一并移除。 */
/* 搜索状态提示行已移除。 */

/* 从 loaderData 里挑出各页面形态的数据
   注意：不同页面的字段层级不同 —— 榜单页是 loaderData[x].content.rankList，
   分类页是 loaderData[x].recommendList，搜索页是 loaderData[x].searchList，
   剧集页是 loaderData[x].seriesDetail，所以 content 要下钻一层。 */
function hgDig(ld){
  var o = { search: null, rec: null, rank: null, detail: null, sel: null, cat: null };
  for (var k in ld) {
    var v = ld[k];
    if (!v || typeof v !== 'object') continue;
    var w = (v.content && typeof v.content === 'object') ? v.content : v;
    if (w.searchList) o.search = w.searchList;
    if (w.recommendList) o.rec = w.recommendList;
    if (w.rankList) o.rank = w.rankList;
    if (v.seriesDetail) o.detail = v.seriesDetail;
    if (w.selectorList && w.selectorList.length) o.sel = w.selectorList[0].items || [];
    if (v.categoryRoute) o.cat = v.categoryRoute.contentType;
    else if (w.categoryRoute) o.cat = w.categoryRoute.contentType;
  }
  return o;
}

