/* 剧集卡片：只取图片 / 名字 / ID。
   注意：点卡片必须进「规则自己的采集页」而不是网页 —— 榜单/二级分类现在都由本页
   原地刷新渲染，而海阔下钻的 dealRule **不拷贝 detail_find_rule**，所以卡片若用
   普通 http 链接会落到「网页打开」分支。改用 hiker://page/ep 子页面
   （pages 会被子规则继承），子页面的 url 由 item.extra.url 指定。 */
/* v35：**列表卡片标题要能看见季号** —— 卡片只有一行宽度，站点给多季剧起的长名字
   （实测「持械入宋：第八季」）在卡片上被截成「持械入宋：第八」，季号看不见。
   规则（按用户指定）：**剧名里含季号时，标题 =「剧名前四个字 + 第N季」**
   （「持械入宋：第八季」→「持械入宋第8季」）；不含季号的剧名原样显示。
   本函数放在 PAGE_LIB：列表页规则（find_rule/searchFind）只带 PAGE_LIB、不带 SEASON_LIB，
   所以自带一份季号解析（逻辑与 SEASON_LIB 的 hgsSeasonNum 一致）。 */
var HG_CN_NUM = { '零':0,'一':1,'两':2,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9 };
function hgSnStr(t){
  t = String(t || '');
  if (/^\d+$/.test(t)) return String(parseInt(t, 10));
  if (t.indexOf('十') >= 0) {
    var p = t.split('十');
    var hi = p[0] ? (HG_CN_NUM[p[0]] || 0) : 1;
    var lo = (p[1] && p[1].length) ? (HG_CN_NUM[p[1]] || 0) : 0;
    return String(hi * 10 + lo);
  }
  return String(HG_CN_NUM[t] != null ? HG_CN_NUM[t] : 1);
}
/* v71：**只取季号标记**（'第8季'）—— 用户要求「封面剧名别改，把第*季放到封面里「全*集」前面」，
   所以剧名原样显示、这个标记用在卡片 desc 的「全N集」前（见 hgCards）。
   本函数放在 PAGE_LIB：列表页规则（find_rule/searchFind）只带 PAGE_LIB、不带 SEASON_LIB，
   所以自带一份季号解析（逻辑与季库里的实现一致）。 */
function hgSeasonTag(name){
  var s = String(name == null ? '' : name).split('\n').join('').trim();
  /* 只认「第N季」（任意位置）或「N季」结尾（站点有「…之无灵证道41季」这种不带「第」的写法）；
     中文数字的裸「N季」不认，免得把《人间四季》这类剧名当成第 4 季。 */
  var m = s.match(/第\s*([0-9]{1,3}|[一二三四五六七八九十]{1,3})\s*季/)
       || s.match(/([0-9]{1,3})\s*季\s*$/);
  if (!m) return '';
  return '第' + hgSnStr(m[1]) + '季';
}
/* v79：版本信息行整块删掉（用户要求：不要列表末尾那行「规则 vX · 逻辑库 vY」）。
   要核对版本时看更新弹窗 / 规则 JSON 的 version 字段即可。 */
/* v80：**漫画分类判定** —— 站点 /category/comic 下面是条漫（图片内容），没有视频流，
   按视频点播必然没反应。判定只看当前页 URL，**0 额外请求**；注意排掉 /category/comic-drama（漫剧=视频）。 */
function hgIsComicPage(){
  try {
    var u = String((typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : ((typeof fyclass !== 'undefined') ? fyclass : ''));
    return u.indexOf('/category/comic') >= 0 && u.indexOf('/category/comic-drama') < 0;
  } catch (e) { return false; }
}
function hgCards(d, list, isRank){
  for (var i = 0; i < list.length; i++) {
    var it = list[i] || {};
    var vd = it.video_data || {};                 /* 搜索结果的剧集数据包在 video_data 里 */
    var sid = it.series_id || it.seriesId || it.id || vd.series_id || '';
    if (!sid) continue;
    var cover = it.series_cover || it.cover || it.pic || vd.series_cover || '';
    var nm = it.series_name || it.title || it.name || vd.series_title || '';
    var _tag = hgSeasonTag(nm);                   /* v71：「第N季」标记（剧名不再改写） */
    var _ep = String(it.episode_right_text || vd.episode_right_text || '');
    var desc = isRank
      ? ((it.rank ? ('No.' + it.rank + '  ') : '') + (it.heatText || '') + (it.scoreText ? ('  ' + it.scoreText) : ''))
      : ((_tag ? (_tag + ' · ' + _ep) : _ep) + '\n' +
         String(it.series_intro || it.description || vd.series_intro || '').substring(0, 40));
    d.push({
      title: nm,
      img: cover + '@Referer=' + HG_SITE,
      desc: String(desc || '').substring(0, 120),
      url: 'hiker://page/ep',
      /* v58：**extra 里必须写死 pageTitle**，否则海阔按「上一页标题 + '-' + 本条标题」拼子页标题
         （反编译：DetailUIHelper.getItemTitle → (activityTitle空?'':activityTitle+'-') + titleText，
          见 ui/detail/DetailUIHelper.java:502-506；BaseExtra.inheritTitle 默认 true 就是这么走）。
         结果就是从演员表连着点几次剧，标题栏会串成「雾锁情迷-嫁神明-明日预言师…」（用户报的问题）。
         写死 pageTitle 后每次进详情页都只显示本条的名字 = 永远的「最后的标题」。 */
      extra: { url: HG_SITE + '/detail?series_id=' + sid + (hgIsComicPage() ? '&comic=1' : ''), pageTitle: nm },
      col_type: 'movie_3'
    });
  }
  /* v79：**列表末尾那行版本号已删**（用户要求）—— 原本放在这里是为了核对「逻辑库热更有没有生效」，
     现在不放了；需要核对时看更新弹窗，或看规则 JSON 里的 version 字段。 */
}
/* v83：**番茄书单卡片**（漫画频道 / 书城小说共用）—— 一级分类里的「漫画」「小说」两条
   不再解析红果网页，书单直接来自番茄 App 接口（FQ）：
   · kind='comic' → 直接进分类目录页 hiker://page/cat（图片阅读整章，不依赖红果网页）
   · kind='novel' → 进小说页 hiker://page/novel（封面/简介 + 目录 + 从第一章开读）
   · v89 kind='audio' → 进听书详情页 hiker://page/audio（封面/简介/公司信息 + 目录 + 播放）
   封面是番茄 CDN 的签名直链，不需要 @Referer。 */
function hgFqCards(books, kind) {
  var out = [];
  for (var i = 0; i < books.length; i++) {
    var b = books[i] || {};
    var id = String(b.book_id || '');
    if (!id) continue;
    var nm = String(b.name || ''), au = String(b.author || '');
    var ab = String(b.abstract || ''), cv = String(b.cover || '');
    var ttl = nm || ('#' + id);
    var url, pg;
    if (kind === 'comic') {
      pg = 'hiker://page/cat';
      url = 'hiker://page/cat?book=' + id + '&nm=' + encodeURIComponent(nm) + '&k=comic';
    } else if (kind === 'audio') {
      pg = 'hiker://page/audio';
      url = 'hiker://page/audio?book=' + id + '&nm=' + encodeURIComponent(nm)
          + '&au=' + encodeURIComponent(au) + '&ab=' + encodeURIComponent(ab.substring(0, 300))
          + '&cv=' + encodeURIComponent(cv);
    } else {
      pg = 'hiker://page/novel';
      url = 'hiker://page/novel?book=' + id + '&nm=' + encodeURIComponent(nm)
          + '&au=' + encodeURIComponent(au) + '&ab=' + encodeURIComponent(ab.substring(0, 300))
          + '&cv=' + encodeURIComponent(cv);
    }
    out.push({
      title: ttl,
      img: cv,
      /* v92：书城/频道书单自带出品方（source），直接显示 —— 判「同一家公司作品系列」一眼可见，
         与详情页的出品方一致，且不花任何额外请求 */
      desc: String((b.source ? '出品：' + b.source + ' · ' : '')
                   + (b.serial_count ? '共' + b.serial_count + (kind === 'comic' ? '话' : '章') + ' · ' : '')
                   + (au ? au + '：' : '') + ab).substring(0, 60),
      col_type: 'movie_3',
      url: pg,
      extra: { url: url, pageTitle: ttl },
    });
  }
  return out;
}
/* v94：**音频直链补媒体标记** —— 番茄 TTS/有声书下发的都是签名 CDN 地址，
   形如 https://v11-fq-tts.fqnovelvod.com/…/…/?a=1967&ch=0&cr=4…&mime_type=audio_mpeg
   ——**没有 .mp3 后缀**。海阔判断「这是不是媒体」只看两样东西
   （UrlDetector.getMediaType：`.mp3/.wav/.ogg/.flac/.m4a` 等扩展名，或 URL 里含
    `isMusic=true` / `isVideo=true`，见 UrlDetector.java:35/59-68），
   两样都不占时被当成 Media.HTML → 点它走 WebUtil.goWebWithExtraData 打开 WebView
   （ArticleListFragment.java:4063-4078），于是「没有播放音源、进去像在看小说」。
   这里统一补上 isMusic=true，海阔就会走 PlayerChooser 起播放器。 */
function hgMusicUrl(u) {
  var s = String(u || '');
  if (!s || s.indexOf('isMusic=true') >= 0 || s.indexOf('isVideo=true') >= 0) return s;
  return s + (s.indexOf('?') >= 0 ? '&' : '?') + 'isMusic=true';
}


/* ---- 缓存占用控制 -----------------------------------------------------------
   手动清理：「搜索/清理」那一行的按钮，空输入时点一下**把本规则缓存全清**（不受 TTL 限制），
      toast 报「删了几个文件 / 释放多少 MB」（v70 起由页面自己跑，见 hgSearchInput + 模板末尾的 rg_gc 处理）。
   红线：只碰本规则前缀（rg/rgs/hgs）的文件，cache 目录里其它规则/其它 App 的文件不碰。
   例外：播放的**运行库**（rglib.js / rgproxy.js / rgapi.js，约 100KB）
         任何清理都不动 —— 它们是本次播放正在读的文件，删了正在看的那一集会直接
         「无播放库」；而且每次进详情页都会重写，也不是占用大头。 */
/* v64：**自动清理整块删掉**（用户要求：有「搜索/清理」按钮就够了）—— 现在只有那个按钮：
   点一下 = 本规则缓存全清（运行库除外）。所以「保留几天/降到多少 MB」的阈值也一并删了。 */

function hgMb2(b){ var m = (Number(b) || 0) / 1048576; return (m >= 100 ? Math.round(m) : Math.round(m * 10) / 10); }
/* 运行库与清理标记：任何清理都跳过（见上面说明） */
function hgClrIsLib(nm){
  /* v76：**云端库缓存也算运行库** —— rg_cloud_lib.js（140KB 逻辑库）+ rg_cloud_stamp.txt（更新时间戳，
     决定 6 小时节流）+ rg_cloud_noted.txt（已提示过的版本）。不保护的话：点一次清理就把它们删掉，
     下次进页面要重新下载整份逻辑库，而且「已提示版本」被清掉会让更新弹窗又弹一次（实测到的）。 */
  return /^(rglib\.js|rgproxy\.js|rgapi\.js|rg_cloud_lib\.js|rg_cloud_stamp\.txt|rg_cloud_noted\.txt)$/.test(nm);
}
/* v38：我们的缓存**分两处**放 ——
   ① `hiker://files/_cache/`：播放密文/明文、预热直链、预取标记、诊断文件、锁与界面状态
      （占地大头）。放这里的好处：**海阔自己的「清除缓存」/它的 _cache 自动清理会把我们这些
      文件一并清掉**，用户不必单独记得来清我们的缓存；
